var (
	DefaultFuzzData    []*rawFile
	DefaultHashDataMap map[string]string // filename: hash-value
)

type rawFile struct {
	fileName string
	content  string
}

func init() {
	DefaultFuzzData = initFuzzData()
	DefaultHashDataMap = initHashDataMap()
}

func initFuzzData() []*rawFile {
	s := strings.Split(fuzz, "\n")
	var list = make([]*rawFile, 0, len(s))
	for _, v := range s {
		fileInfo := strings.Split(v, ":")
		m, _ := base64.StdEncoding.DecodeString(strings.TrimSpace(fileInfo[1]))
		list = append(list, &rawFile{fileName: fileInfo[0], content: BytesToString(m)})
	}

	return list
}

func initHashDataMap() map[string]string {
	s := strings.Split(hash, "\n")
	var h = make(map[string]string, len(s))

	for _, v := range s {
		fileInfo := strings.Split(v, ":")
		h[strings.TrimSpace(fileInfo[1])] = strings.TrimSpace(fileInfo[0])
	}

	return h
}
